  'settings.reconnect.policy': 'מתי זה קורה מעצמו',
  'settings.reconnect.policyHint': 'התחברויות מחדש אוטומטיות מופעלות במקום אחד בלבד, והדף הזה אינו אותו מקום. אחת מתחילה כשמנוע ההורדה עצמו מבקש ניסיון נוסף אחרי המתנה, וכך מארח אומר שהמגבלה קשורה לכתובת הזו. היא לעולם לא רצה בזמן שהתור עצור, כי אתחול הנתב מפיל את ההורדות שעדיין רצות. היא לעולם לא רצה כל עוד ההתחברות מחדש אינה מוגדרת במלואה. רצה רק אחת בכל רגע: בקשה שנייה ממתינה לפסיקה של הראשונה במקום להיאבק איתה על הנתב. ואם הכתובת לא זזה, שום דבר לא מוקדם, והמתנת הניסיון החוזר הרגילה ממשיכה כרגיל.',

