  'settings.chunksHint': 'כמה חיבורים פותחת הורדה אחת כשאין משהו מדויק יותר שחל. כלל, או הורדה בודדת, יכולים לנקוב במספר משלהם והם גוברים על זה. מארח שסובל פחות יקבל פחות ממילא: מגבלת מארח יכולה רק להוריד את המספר, לעולם לא להעלות אותו. עם 0 ההחלטה נשארת לאפליקציה. יותר מקומץ חיבורים לא מוסיף דבר אצל מארח שמגביל לכל קובץ, וזו דרך בטוחה לסמן חשבון.',
