  'props.name': 'שם',
  'props.nameHint': 'שם קובץ אחד, לעולם לא נתיב: כל דבר שמפרט תיקיות נחתך לשם יחיד. הורדה שהסתיימה משנה שם גם על הדיסק, כדי שהרשימה והתיקייה לא יוכלו לסתור זו את זו. הורדה שרצה שומרת על הקובץ שהמנוע שלה מחזיק פתוח, ולוקחת את השם החדש כשהיא נגמרת. הורדה שטרם התחילה לוקחת אותו מיד. שם שייך לקובץ אחד, ולכן התיבה הזאת מוצעת רק לשורה בודדת.',
