  'settings.access.ownRelay.containerLabel': 'כמכולה נפרדת',
  'settings.access.ownRelay.containerHint': 'אם אף מופע שלך אינו נגיש מבחוץ, הממסר צריך לשבת במקום אחר: בשרת שלך או ב-VPS קטן. התקן את הקונטיינר מ-Unraid Community Applications או בעזרת הפקודה שלמטה.\n\nהקונטיינר לא דורש הגדרות: הפעל אותו, הזן את הכתובת שלו למעלה, וזהו. הוא לא שומר כלום, ולכן אין מה לגבות.',
