  'settings.access.phrase.howStep1': 'במופע הזה לחצו על "{button}". יופיעו שתים־עשרה מילים.',
  'settings.access.phrase.howStep2': 'פתחו את KnightLoader במכשיר השני, היכנסו לאותו עמוד, לחצו על "{button}" והקלידו את שתים־עשרה המילים.',
  'settings.access.phrase.howStep3': 'מוכן! כל מופע מופיע כעת אצל השני תחת „מופעים”, ואפשר להפעיל כל אחד מכל אחד. כשהממסר מופעל, המופעים שלך זמינים גם מחוץ לרשת שלך.',
  'settings.access.phrase.howWhat': 'המילים הן סוד, לא כתובת. כל מופע מחשב מהן שני מפתחות: אחד כדי למצוא את האחרים ואחד להצפנה.\n\nכדי למצוא זה את זה, כל מופע מתקשר מיוזמתו לאותה נקודת מפגש באינטרנט. מי שמציג את אותו מפתח מחובר. לכן אף מופע שלך לא צריך להיות נגיש מבחוץ.\n\nנקודת המפגש לא יכולה לקרוא. היא לעולם לא רואה את המילים שלך, וכל מה שעובר דרכה מוצפן במפתח השני.',
