  'settings.resolvers.intro': 'הגדרות עבור ה-backend של yt-dlp, שמביא את אתרי המדיה והסטרימינג ש-yt-dlp עצמו תומך בהם. איזה שירות בכלל מטפל בקישור נתון - yt-dlp, חשבון debrid, ה-sidecar חסר-הממשק של JD - נקבע לפי סדר הניתוב בעמוד חשבונות; כאן מתואר רק מה ש-yt-dlp עושה לאחר שקישור כבר נותב אליו.',
