  'settings.torrents.portMapHint': 'מבקש מהנתב להעביר את הפורט שלמעלה למחשב הזה דרך UPnP, כך שעמיתים מאחורי נתב אחר יוכלו להגיע אליו בכל זאת. לא כל נתב תומך בכך, וחלקם מקבלים את הבקשה מבלי שהיא באמת עובדת.',
