  'settings.torrents.networkTitle': 'איתור עמיתים',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'מוצא עמיתים ללא כל טרקר, באמצעות שימוש בלקוחות BitTorrent אחרים כמדריך מבוזר.',
  'settings.torrents.pex': 'החלפת עמיתים (PEX)',
  'settings.torrents.pexHint': 'מחליף עמיתים ידועים עם אלה שכבר מחוברים, כך שנחיל עם מעט עמיתים נמצא מהר יותר.',
  'settings.torrents.privateNote': 'טורנט פרטי מכבה את שניהם אוטומטית ברגע שהמטא-נתונים שלו ידועים, ללא קשר להגדרה כאן - באופן מיידי עבור קובץ torrent. שהועלה, או ברגע שהמטא-נתונים העצמיים של קישור מגנט מגיעים מהנחיל. רוב הטרקרים הפרטיים חוסמים חשבונות המשתמשים באחד מהם.',
  'settings.torrents.engineNote': 'יחס ההזרעה היעד, משך ההזרעה היעד והפורט מגיעים כעת לכל טורנט שהמנוע הזה מתחיל - הפורט, לעומת זאת, רק עבור הטורנט הראשון ביותר מאז ההפעלה מחדש האחרונה של מופע זה, מכיוון שלקוח הטורנטים של המנוע עצמו נבנה פעם אחת בלבד ואף פעם לא נבנה מחדש לאחר מכן; שמירה מאוחרת יותר עדיין נשמרת כהלכה ונכנסת לתוקף החל מההפעלה מחדש הבאה. מגבלת ההעלאה עדיין רק נשמרת ומאומתת, ואין למנוע עדיין דרך להחיל אותה על הורדה פעילה. ה-DHT וה-PEX למטה נמצאים באותו מצב עבור טורנט רגיל (לא פרטי): גם ברירת המחדל של מופע זה עדיין לא מגיעה להורדה פעילה, כך שטורנט ממשיך להיות מוזרע עם שניהם פעילים ללא קשר להגדרה כאן - טורנט פרטי הוא מקרה שונה לגמרי, ראה את ההערה למטה. עם זאת, כפתור המיפוי למטה עושה משהו אמיתי: הוא מבקש בכנות מהנתב להעביר את מספר הפורט שהוזן למעלה, בין אם טורנט מאזין לו כרגע ובין אם לא.',
