  'onboarding.welcome.title': 'ברוך הבא ל-KnightLoader',
  'onboarding.welcome.body': 'KnightLoader הוא מנהל הורדות בארחון עצמי: הדבק או גרור קישור, והוא נאסף על ידי כל צד אחורי שבאמת מטפל בו - המנוע המובנה לקישורי קבצים פשוטים, yt-dlp לדפי מדיה, שירות דיבריד למארחים שאתה כבר משלם עבורם, או JDownloader ללא ממשק לכל השאר. הסיור הקצר הזה מכסה את ההגדרה היחידה ששווה לבדוק לפני שמתחילים.',
  'onboarding.welcome.langLabel': 'שפת הממשק',
