  'onboarding.folder.body': 'זו התיקייה שאליה נכתבות הורדות שהושלמו. הקלד נתיב או עיין בשרת כדי לבחור אחת - אפשר לשנות אותה שוב בכל עת מעמוד ההגדרות הכלליות.',
  'onboarding.accounts.title': 'מארחי פרימיום, מתי שתרצה',
  'onboarding.accounts.body': 'התור עובד גם בלי שום חשבון. כשתרצה מהירות מלאה אצל מארח או שירות דיבריד שאתה כבר משלם עבורו, הוסף את פרטי ההתחברות שלו תחת חשבונות - אין צורך להגדיר כאן שום דבר עכשיו.',
