  'notifications.titleHint': 'החלט לכל אירוע אם הוא מופיע כבועה באפליקציה, כהתראה של מערכת ההפעלה שלך, או בכלל לא. התראת מערכת מגיעה אליך רק כל עוד לשונית של KnightLoader פתוחה, ומצב שקט שלמטה חל על זה בנוסף.',
