  'notifications.event.extractionFailed': 'החילוץ נכשל',
  'notifications.event.extractionFailedHint': 'ארכיון שנעצר בלי לסיים. בדרך כלל חסרה סיסמה, והקבצים נשארים במקומם עד שתטפל בזה.',
  'notifications.event.captchaWaiting': 'קאפצ׳ה ממתינה',
  'notifications.event.captchaWaitingHint': 'חלון הקאפצ׳ה נפתח בלשונית הזאת כך או כך. זה מתחיל ב„לא להציג כלום”, כי החלון הזה הוא כבר ההודעה כל עוד אתה מסתכל עליו. קבע אותו להתראת מערכת, ואז קאפצ׳ה בלשונית רקע תגיע אליך לפני שהמארח משליך את ההפעלה.',
  'notifications.event.captchaFailed': 'קאפצ׳ה נכשלה',
  'notifications.event.captchaFailedHint': 'אף אחד לא ענה בזמן, או שהתשובה לא עברה. ההורדה שמאחוריה נשארת במקומה.',
  'notifications.event.captchaResolved': 'קאפצ׳ה נענתה במקום אחר',
  'notifications.event.captchaResolvedHint': 'מישהו בדפדפן אחר, או פותר אוטומטי, ענה עליה והחלון נסגר מעצמו.',
  'notifications.systemUnavailable': 'התראות מערכת אינן זמינות כאן: הדפדפן שלך מציע אותן רק ב-HTTPS או ב-localhost. כל מה שבכרטיס הזה עדיין מוצג באפליקציה.',
  'notifications.systemBlocked': 'הדפדפן שלך חוסם התראות עבור הכתובת הזאת. שורות שנקבעו ל„התראת מערכת” מוצגות במקום זאת באפליקציה, עד שתרשה אותן שוב בהגדרות האתר בדפדפן שלך.',
  'notifications.systemNotGranted': 'הדפדפן לא נתן הרשאה, ולכן האירוע הזה נשאר באפליקציה. בחר שוב ב„התראת מערכת” כדי לשאול עוד פעם.',
