  'events.title': 'אירועים',
  'events.open': 'פתיחת רשימת האירועים',
  'events.titleHint': 'כל התראה שהחלון הזה מציג לך נוחתת גם כאן, כך שאפשר לקרוא שוב אחת שהבועה שלה כבר נעלמה. נשמרות {max} האחרונות, ובכל טעינה מחדש של העמוד הרשימה מתחילה מהתחלה.',
