  'idleAction.problem.empty': 'לא הוגדרה שום תוכנית, ולכן אין מה להריץ. הזן למעלה את הנתיב המלא של התוכנית.',
  'idleAction.problem.notFound': '{program} לא קיימת על המופע הזה.',
  'idleAction.problem.notFoundContainer': '{program} לא קיימת בתוך הקונטיינר הזה. כאן יש רק את מה שהאימג׳ מביא איתו: אין systemd, אין curl, אין ssh, אין sudo. הנח את הפקודה על המארח וקרא לה מכאן, או הצבע כאן על סקריפט שעיגנת לתוך הקונטיינר.',
  'idleAction.problem.notExecutable': '{path} קיים, אבל אי אפשר להריץ אותו. תן לו הרשאת הרצה ודאג שהמשתמש שתחתיו רץ התהליך הזה יוכל לקרוא אותו: בקונטיינר זה uid 1000, לא root.',
  'idleAction.problem.permission': 'המערכת סירבה: לתהליך הזה אין הרשאה לכך. בקונטיינר הוא רץ כ-uid 1000, בלי root ובלי שום גישה אל המארח. לכן כל מה שמשנה את מצב החשמל של המכונה חייב לקרות על המארח עצמו.',
  'idleAction.problem.timeout': 'התוכנית עוד רצה אחרי {seconds} שניות ונעצרה. בהחלט ייתכן שהיא עשתה את שלה בכל זאת. העלה את המגבלה אם הפקודה אמורה לקחת יותר זמן.',
  'idleAction.problem.exit': 'התוכנית הפסיקה עם קוד {code}. הפלט שלה עצמה: {output}',
  'idleAction.problem.notSupported': 'הבילד הזה לא יכול לבצע את זה. בחר פעולה אחרת לסיום התור.',
  'idleAction.problem.suspendRefused': 'המערכת סירבה להיכנס למצב שינה. בלינוקס בדרך כלל ניהול ההרשאות רוצה אישור שהאפליקציה הזאת לא יכולה לתת: התר למשתמש שלך להיכנס למצב שינה, או עבור אל „להריץ פקודה” והעבר את המכונה למצב שינה דרך סקריפט משלך.',
  'idleAction.runFailed': 'לא ניתן היה להתחיל את הפקודה.',
