  'idleAction.dismiss': 'הסתר',
  'settings.transfer.title': 'רק ההגדרות',
  'settings.transfer.hint': 'כותב את settings.json לקובץ אחד: מגבלות התור, התיקיות, מערכי הכללים, הקטגוריות ולוח הזמנים. לא את רשימת ההורדות ולא את ההיסטוריה. את הקובץ שומר הדפדפן שלך, והוא לא הולך לשום מקום אחר.',
  'settings.transfer.export': 'ייצוא ההגדרות',
  'settings.transfer.exportHint': 'שומר קובץ JSON אחד. ייבא אותו במכונה החדשה ובחר שם מה יועבר.',
  'settings.transfer.import': 'ייבוא ההגדרות',
  'settings.transfer.importHint': 'לפני שראית את הרשימה ואישרת אותה, שום דבר לא נכתב. משתנה רק מה שתבחר, כל השאר נשאר כפי שהוא כאן. בלי הפעלה מחדש.',
  'settings.transfer.withSecrets': 'לכלול את הסיסמאות השמורות',
  'settings.transfer.withSecretsHint': 'דלוק: הקובץ נושא את סיסמת הנתב, כל סיסמת פרוקסי וכל סיסמת ארכיון בטקסט גלוי. כבוי: השדות האלה מגיעים ריקים במכונה האחרת ואתה מקליד אותם פעם אחת. בשני המקרים עדיין ייתכן שסוד יושב במקום שאיש כאן לא מזהה: כתובת פיד שיש בה מפתח API, או סיסמה שכתבת לתוך סקריפט התחברות מחדש.',
  'settings.transfer.notTravellingLabel': 'מה שלעולם לא נוסע איתו',
  'settings.transfer.notTravelling': 'מה שהקובץ הזה לעולם לא מחזיק: פרטי הכניסה שלך ל-debrid ולמארחים, פרופילי הכותרות, מפתחות הקאפצ׳ה, סיסמת הכניסה לממשק הזה והסקריפטים שלך. אלה יושבים חתומים מחוץ ל-settings.json, וגם הארכיון המלא לא נושא אותם. אותם תגדיר מחדש במכונה החדשה.',
  'settings.transfer.previewTitle': 'מה להעביר?',
