  'settings.transfer.previewSecretless': 'הקובץ הזה יוצא בלי סיסמאות. השורות המסומנות למטה מגיעות בלי שלהן.',
  'settings.transfer.colStored': 'כאן עכשיו',
  'settings.transfer.colFile': 'בקובץ',
  'settings.transfer.same': 'זהה',
  'settings.transfer.unknownKey': 'הבילד הזה לא מכיר את ההגדרה הזאת, ולכן אי אפשר להעביר אותה.',
  'settings.transfer.identityKey': 'שייך למכונה הזאת ולעולם אינו מועבר',
  'settings.transfer.identityKeyHint': 'דרך מזהה המופע פונים הממסר וכל השכנים המצומדים אל המכונה הזאת. שתי מכונות שנושאות את אותו מזהה מתנגשות באותה קבוצה, ולכן הוא נשאר במקום שבו נוצר.',
  'settings.transfer.noPassword': 'מגיע בלי הסיסמה שלו. הקלד אותה אחר כך.',
  'settings.transfer.wholeList': 'מחליף את כל הרשימה כאן, שורה מול שורה',
