  'settings.module.metrics': 'כתובת מדדים למערכת ניטור',
  'settings.health.title': 'המצב כרגע',
  'settings.health.titleHint': 'העמוד הזה רק קורא. שום דבר בו לא מתחיל, לא עוצר ולא משנה דבר, וגם אם תשאיר אותו פתוח זה לא משנה כלום. הערכים נמשכים כל עשר שניות. אם משיכה נכשלת, הקריאה האחרונה נשארת עומדת במקום שהעמוד יתרוקן. החלקים שצריך לתשאל אותם משותפים לחצי דקה, ולכן מה שאתה רואה כאן יכול לפגר עד שלושים שניות אחרי השורות בעמוד ההורדות.',
  'settings.health.version': 'גרסה',
  'settings.health.uptime': 'רץ מזה',
  'settings.health.uptimeHint': 'כמה זמן התהליך הזה רץ, לא כמה זמן המכונה רצה. קונטיינר שהופעל מחדש לפני שעה מתחיל כאן שוב מאפס, מה שלא יגיד המארח. התאריך שלצדו הוא השעון של השרת עצמו, לא של הדפדפן שלך.',
  'settings.health.startedAt': 'הופעל',
  'settings.health.sampled': 'נקרא לפני {n} שניות',
  'settings.health.loadFailed': 'לא ניתן היה לטעון את המצב. האם השרת זמין?',
  'settings.health.oldHealthHint': 'הכתובת הישנה /api/health לא השתנתה וממשיכה לענות "ok" כל עוד התהליך הזה רץ, מה שלא יהיה כתוב בעמוד הזה. זה במכוון: בדיקת התקינות של הקונטיינר, גשר ה-Click\'n\'Load וחיפוש המופעים של אפליקציית הטלפון קוראים אותה כולם, ותשובה אחרת מ-"ok" הייתה מסמנת את הקונטיינר כלא תקין וגורמת לטלפון להפסיק למצוא את המופע הזה. תקלה מדווחת בעמוד הזה. אותה כתובת רק אומרת אם מישהו בכלל מאזין.',
