  'settings.health.parts': 'חלקים',
  'settings.health.partsHint': 'שורה אחת לכל חלק של האפליקציה שיכול ליפול בפני עצמו. חלק שמעולם לא הגדרת במופע הזה אומר את זה, במקום להיחשב תקלה, וחלק שהבילד הזה לא יכול לשאול אותו אומר את זה גם כן. זו תשובה שלישית ולא אפס שקט. לקרוא שורה לא משנה דבר: חלק שאומר שהוא לא עובד כבר נופל זמן מה, כאן אתה רק רואה את זה.',
  'health.part.store': 'מסד נתונים',
