  'health.part.accounts': 'חשבונות מארחים',
  'health.part.feeds': 'מינויים לפידים',
  'health.part.relay': 'ממסר',
  'health.part.captcha': 'קאפצ׳ות',
  'health.remedy.store.failed': 'מסד הנתונים לא ענה. ההורדות ממשיכות לרוץ, אבל שום דבר עליהן כבר לא נרשם, ולכן הפעלה מחדש תאבד את כל מה שהשתנה מאז. בדוק שתיקיית הנתונים עדיין מעוגנת ועדיין ניתנת לכתיבה.',
  'health.remedy.jd.unreachable': 'KL_JD נוקב בכתובת שהמופע הזה לא מגיע אליה כרגע. בדוק שהקונטיינר של JDownloader רץ ושפורט ה-API שלו עונה מכאן. קישורים שרק JDownloader יכול להביא נשארים בינתיים בתור, והם לא נכשלו.',
  'health.remedy.jd.notWired': 'JDownloader עונה שוב, אבל התהליך הזה חיווט את ה-backends שלו בזמן ההפעלה ואז הוא לא היה שם. הפעל את KnightLoader מחדש כדי שהוא ייקלט.',
  'health.remedy.ytdlp.missing': 'בזמן ההפעלה לא נמצא שום yt-dlp (KL_YTDLP, או "yt-dlp" ב-PATH). עמודי מדיה נכשלים אז עם השגיאה של האתר עצמו במקום להיפרש לוריאנטים. כדי שהוא יימצא, צריך להפעיל מחדש.',
  'health.remedy.disk.low': 'תיקיית יעד נמצאת מתחת לרצפה שקבעת בעמוד ההורדות. שם לא מתחיל שום דבר חדש עד שיהיה מקום שוב, או עד שתוריד את הרצפה. מה שכבר רץ לא נעצר על ידי הרצפה הזאת.',
  'health.remedy.disk.elsewhere': 'תיקייה אינה שם, ולכן המספרים מתארים את התיקייה הקרובה שמעליה. אם עיגון לא עלה, זה דיסק אחר לגמרי. הסתכל על הנתיב לפני שאתה מאמין למספרים.',
  'health.remedy.accounts.benched': 'לפחות חשבון מארח אחד מונח בצד אחרי כישלון. הוא ינוסה שוב מעצמו כשההמתנה תיגמר, וההמתנה מוכפלת בכל פעם. פתח את עמוד החשבונות ולחץ על „רענן” בשורה אם אתה רוצה לדעת עכשיו.',
  'health.remedy.accounts.invalid': 'לפחות חשבון מארח אחד נדחה. מפתח חדש או מינוי שחודש פותרים את זה, המתנה לא.',
  'health.remedy.feeds.failing': 'אצל מינוי אחד לפחות המשיכה האחרונה נכשלה. איזה ולמה, כתוב בעמוד ההורדות ליד הפיד ובשורות היומן בעמוד האבחון.',
  'health.remedy.relay.down': 'כתובת ממסר שמורה והחיבור לא עומד. המופע הזה ממשיך לנסות מעצמו, ומקומית הכול עובד כרגיל. רק מבחוץ הוא לא נגיש כרגע.',
  'health.remedy.captcha.waiting': 'backend אחד עצר ושואל בן אדם. מאחוריו שום דבר לא זז עד שמישהו יענה.',
  'settings.health.tasks': 'ההורדות כרגע',
  'settings.health.tasksHint': 'תמונת מצב של הרשימה כפי שהיא עומדת, לא מניין לאורך זמן. „נכשלו” סופר את השורות שיושבות ברשימה עם שגיאה עליהן. המספר יורד כשאתה מפנה אותן וכשהרשימה מתנקה אחרי מספר הימים שהגדרת, והוא עולה שוב כשמשהו חדש משתבש. שום דבר כאן אינו קצב, ושום דבר כאן לא אומר כמה פעמים משהו נכשל.',
  'settings.health.running': 'רצות',
  'settings.health.waiting': 'ממתינות',
