  'settings.health.nothingWaiting': 'שום דבר לא מוחזק.',
  'settings.health.nothingFailed': 'ברשימה שום דבר לא נכשל.',
  'settings.health.diskLink': 'כמה מקום יש בתיקיות היעד, כתוב בעמוד ההורדות',
  'settings.health.scrape': 'ניטור',
  'settings.health.scrapeSwitch': 'לענות בכתובת המדדים',
  'settings.health.scrapeHint': 'פותח כתובת שנייה שמוציאה את אותם ערכים כטקסט פשוט, בפורמט ש-Prometheus והכלים שנבנו לפיו קוראים. אותה מושכים, ולעולם לא שולחים: שום דבר לא עוזב את המכונה הזאת כל עוד הניטור שלך עצמך לא בא לכאן ומבקש. כל עוד זה כבוי, הכתובת בכלל לא קיימת והיא עונה 404, בדיוק כמו כל כתובת אחרת שאין לאפליקציה הזאת. במופע עם סיסמה המשיכה דורשת אחד מאסימוני ה-API שלך, ואת זה אפשר ללמד כל אספן מדדים. אספן לא שולח כותרת Origin ולכן הוא עובר. לשונית דפדפן בכתובת אחרת כן שולחת אחת, והיא נדחית כשהיא לא מתאימה לכתובת של המופע הזה עצמו. בטקסט כתובים הנתיבים של תיקיות היעד שלך, ולכן תן אותו רק לאן שהיית נותן גם את שמות התיקיות עצמם.',
