  'settings.health.scrapeCopied': 'הכתובת הועתקה',
  'settings.health.scrapeOffHint': 'הכתובת הזאת לא עונה כלום כל עוד המתג שלמעלה כבוי.',
  'settings.diagnostics.systemTitle': 'פרטי מערכת',
  'settings.diagnostics.fileTitle': 'קובץ היומן',
  'settings.diagnostics.fileOn': 'לכתוב את היומן לקובץ',
  'settings.diagnostics.fileOnHint': 'כבוי עד שתדליק, ועדכון לעולם לא מדליק את זה בשבילך. כשזה דלוק, המופע הזה כותב כל שורה שהוא מתעד לקובץ בתיקיית הנתונים שלו, כך שקריסה משלשום עדיין ניתנת לקריאה אחרי הפעלה מחדש. שורת יומן יכולה לנקוב בכתובת של פיד שאתה מנוי עליו, ולכן התייחס לקובץ כאל שלך. בקונטיינר אותן שורות מגיעות ממילא אל docker logs, והקובץ הוא מה שנשאר אחרי שאלה כבר חלפו.',
