  'settings.owner.identityTitle': 'בתור מי המופע הזה כותב',
  'settings.owner.identityHint': 'כל קובץ שהמופע הזה יוצר מקבל את הבעלים האלה ואת ההרשאות האלה, וכך גם כל מה שהוא מפעיל: yt-dlp, ffmpeg וה-JDownloader המצורף. בקונטיינר הזהות נקבעת ברגע שהקונטיינר עולה, לפי החשבון שתחתיו הופעל, ומהעמוד הזה אי אפשר לשנות בה דבר.',
