  'settings.owner.envHow': 'אם אתה רוצה לרוץ תחת חשבון אחר, נקוב בו בפקודת ההפעלה: --user <uid>:<gid>. ב-Unraid זה שייך ל-Extra Parameters, וצריך ליצור את הקונטיינר מחדש כדי שזה יתפוס.',
  'settings.owner.desktopNote': 'אפליקציית שולחן העבודה רצה תחת החשבון שלך עצמך. PUID, PGID ו-UMASK הם הגדרות של קונטיינר ולא עושים כאן דבר.',
  'settings.owner.noOwners': 'במערכת הזאת אין בעלים לקבצים, ולכן אין מה להשוות. זו אינה תקלה.',
  'settings.owner.checkTitle': 'בדיקת התיקיות',
  'settings.owner.checkHint': 'כאן באמת נכתבים קובץ אחד ותת-תיקייה אחת לכל תיקייה, אחר כך נבדק למי שניהם שייכים ומי עוד רשאי לקרוא אותם, ושניהם מוסרים שוב. את זה צריך למדוד ואסור לחשב: שיתוף יכול להביא איתו כללי הרשאות משלו, ותיקייה עם set-group-id מחלקת קבוצה אחרת מזו שיש לתהליך הזה. הבדיקה רצה מעצמה אחרי ששמרת תיקייה שהשתנתה, ותמיד כשאתה לוחץ על הכפתור.',
  'settings.owner.run': 'לבדוק את התיקיות עכשיו',
