  'settings.owner.v.ok': 'קבצים נוחתים כאן בתור {fileOwner} עם {fileMode}, תת-תיקיות חדשות עם {subdirMode}, והתיקייה עצמה שייכת ל-{dirOwner}. אין בזה שום דבר חריג.',
  'settings.owner.v.ownerMismatch': 'קבצים נוחתים כאן בתור {fileOwner}, אבל התיקייה שייכת ל-{dirOwner}. קריאה בדרך כלל עדיין עובדת, שינוי שם, העברה ומחיקה מחשבון אחר כבר לא, וכל מה שמצפה שהתיקייה תהיה הבעלים של מה שבתוכה מחשיב את הקבצים האלה לזרים.',
