  'settings.owner.v.unknown': 'במערכת הזאת אין בעלים לקבצים, ולכן כאן אין מה להשוות. זו אינה תקלה.',
  'settings.owner.fix.user': 'הפעל את הקונטיינר תחת החשבון שאליו שייכת התיקייה: --user {dirUid}:{dirGid} בפקודת ההפעלה. ב-Unraid זה שייך ל-Extra Parameters.',
