  'settings.owner.fix.mask': 'את זה המופע הזה לא יכול לשנות. המסכה מגיעה ממה שהפעיל את הקונטיינר, ושיתוף מעוגן יכול לכפות אחת משלו דרך אפשרות umask, file_mode או dir_mode. תקן את זה במקום שבו התיקייה מעוגנת.',
  'settings.owner.fix.recreate': 'פקודת הפעלה שהשתנתה דורשת יצירה מחדש של הקונטיינר. הפעלה מחדש לא מספיקה: הזהות נקבעת ברגע שהוא עולה.',
  'settings.owner.fix.past': 'קבצים שכבר ירדו שומרים על הבעלים שאיתו נכתבו. מה שתשנה חל על כל מה שבא מכאן והלאה, לשאר צריך את הפקודה שלמעלה.',
  'settings.selftest.title': 'בדיקה עצמית',
