  'settings.selftest.relay.ownNoAddress': 'נבחר ממסר משלך ולא הוגדרה כתובת, ולכן לא מחייגים לשום מקום.',
  'settings.selftest.relay.badSecret': 'אי אפשר לקרוא את סוד החיבור השמור. הזן שוב את משפט החיבור.',
