  'settings.diagnostics.fix.missing': 'התיקייה אינה שם. הקרובה ביותר מעליה שכן קיימת היא {measured}. במכונה שמעגנת שיתוף זה בדרך כלל אומר שהשיתוף אינו מעוגן, וכאן במכוון לא נוצר דבר: תיקייה שנוצרת מתחת לעיגון חסר קולטת את ההורדות במקומו, והן נעלמות עם עדכון הקונטיינר הבא.',
  'settings.diagnostics.fix.denied': 'התיקייה קיימת, ולמופע הזה אסור לכתוב בה. בקונטיינר KnightLoader רץ כ-uid 1000, ולכן התיקייה חייבת להיות שייכת למשתמש הזה או לקבוצה שהוא נמצא בה.',
  'settings.diagnostics.fix.readonly': 'מערכת הקבצים שמתחת לתיקייה הזאת מעוגנת לקריאה בלבד. שום דבר שהמופע הזה עושה לא משנה את זה, העיגון עצמו צריך להשתנות.',
  'settings.diagnostics.fix.full': 'על הכונן שהתיקייה הזאת יושבת עליו לא נשאר מקום.',
  'settings.diagnostics.fix.notRemoved': 'את קובץ הבדיקה ניתן היה לכתוב, אבל לא למחוק שוב. הורדה הייתה מגיעה לכאן ואחר כך לא הייתה משנה שם ולא זזה מהדרך לעולם. הסתכל על הרשאת המחיקה של התיקייה, לא על הרשאת הכתיבה.',
  'settings.diagnostics.fix.notADir': 'בנתיב הזה יושב קובץ, לא תיקייה.',
  'settings.diagnostics.fix.timeout': 'התיקייה לא ענתה בזמן והושארה בשקט. שיתוף שהשרת שלו כבוי מתנהג בדיוק ככה, וגם כזה שברשת שנעלמה.',
  'settings.diagnostics.fix.dataDenied': 'זו התיקייה האחת שהמופע לא יכול בלעדיה: מסד הנתונים, ההגדרות ומאגר החשבונות המוצפן יושבים כאן. ההורדות ממשיכות לרוץ בינתיים, והדבר הבא שתשמור ילך לאיבוד.',
  'settings.diagnostics.fix.javaMissing': 'לא נמצא Java. האימג׳ של הקונטיינר מביא אחד איתו, התקנת שולחן עבודה משתמשת בסביבת הריצה המצורפת או באחת שב-PATH. בלי Java ה-JDownloader הפרטי לא עולה, ולכן קישור מכל מוצפן (‎.dlc, ‎.ccf, ‎.rsdf) לא נפתח בכלל. הגדר את JAVA_HOME, או הצבע עם KL_JD על JDownloader שרץ במקום אחר.',
  'settings.diagnostics.fix.javaNotNeeded': 'המופע הזה לא מפעיל תהליך Java משלו: או ש-KL_JD מצביע על JDownloader שרץ במקום אחר, או שהפרטי כבוי עם KL_PROVISION_JD=0.',
  'settings.diagnostics.fix.ytdlpMissing': 'yt-dlp לא נמצא (KL_YTDLP, או „yt-dlp” ב-PATH). עמודי מדיה נכשלים אז עם הודעת השגיאה של האתר עצמו במקום לרדת.',
  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg לא נמצא. yt-dlp צריך אותו כדי לחבר את מסלולי התמונה והשמע הנפרדים שרוב האתרים מוסרים, ולכן הורדה נעצרת באחד מהשניים או חוזרת בלי שמע.',
  'settings.diagnostics.fix.ffprobeMissing': 'ffprobe לא נמצא. רק בדיקת האורך של וידאו גמור משתמשת בו, כל השאר רץ גם בלעדיו.',
  'settings.diagnostics.fix.notRunnable': 'נמצא תחת {subject}, אבל הוא לא רץ: {error}',
  'settings.diagnostics.fix.appearedLate': 'הוא רץ עכשיו, ובזמן שהמופע הזה עלה הוא לא היה שם, ולכן עדיין לא מנתבים אליו דבר. כדי שייכנס לשימוש, הפעל מחדש.',
  'settings.diagnostics.fix.utcFallback': 'TZ עומד על {subject}, והמופע הזה לא הצליח לטעון את האזור הזה, ולכן הוא נפל חזרה ל-UTC בלי לומר על כך דבר בשום מקום. עד שזה יתוקן, כל חלון בלוח הזמנים רץ על UTC. בדוק את הכתיב מול רשימת האזורים („Europe/Berlin”), ובדוק אם באימג׳ יש בכלל מסד אזורי זמן.',
  'settings.diagnostics.fix.noZoneDatabase': 'במערכת הזאת אין מסד אזורי זמן, ולכן זמנים נקראים בלי שום מעבר לשעון קיץ. חלון לילי שומר על שעת החורף שלו לאורך כל הקיץ, ואף אחד לא מודיע כשזה קורה.',
  'settings.diagnostics.fix.tzUnset': 'TZ לא מוגדר ולא נמצאה שעה מקומית, ולכן המופע הזה רץ על UTC. זה עובד, וכדאי לדעת: חלון בלוח הזמנים שכתוב בו 23:00 מתכוון ל-23:00 UTC, לא ל-23:00 אצלך.',
  'settings.resolvers.toolsTitle': 'כלים',
  'settings.resolvers.toolsHint': 'yt-dlp קורא את עמוד המדיה, ffmpeg מחבר את המסלולים שיוצאים משם. שניהם תוכניות נפרדות ש-KnightLoader מפעיל, ואף אחת מהן לא נמצאת בתוך הבילד הזה. לכן הגרסאות שלהן מעניינות: yt-dlp מיושן הוא הסיבה הנפוצה ביותר לכך שקישור מדיה שעבד בחודש שעבר מפסיק לעבוד.',
  'settings.resolvers.toolsInUse': 'בשימוש',
  'settings.resolvers.toolsNotFound': 'לא נמצא',
  'settings.resolvers.toolsFrom.managed': 'עותק משלו של KnightLoader',
