  'settings.resolvers.toolsFrom.path': 'נמצא ב-PATH',
  'settings.resolvers.toolsFrom.none': 'בשום מקום',
  'settings.resolvers.toolsYtdlpMissingHint': 'בלי yt-dlp אין בכלל צד אחורי למדיה: קישור לעמוד וידאו נדחה עם הודעת השגיאה של האתר עצמו במקום לרדת. בקונטיינר הוא מגיע מחבילת yt-dlp שבאימג׳, על שולחן העבודה אתה מתקין אותו בעצמך ואז שם אותו ב-PATH או מצביע עליו עם KL_YTDLP. הכפתור שלמטה מביא עותק משלו אם שתי הדרכים לא באות בחשבון.',
  'settings.resolvers.toolsFfmpegMissingHint': 'בלי ffmpeg, yt-dlp לא יכול לחבר את מסלולי התמונה והשמע הנפרדים שרוב האתרים מוסרים, ולכן הורדה נוחתת כמסלול וידאו אילם או נכשלת לגמרי. בלי ffprobe, „בדיקת הקובץ הגמור” שלמעלה בעמוד הזה לא מודדת דבר ולא אומרת על כך כלום. בקונטיינר שניהם מגיעים מחבילת ffmpeg שהאימג׳ מתקין, על שולחן העבודה אתה מתקין אותם בעצמך ושם אותם ב-PATH.',
  'settings.resolvers.toolsShadowed': 'רץ עותק משלו של KnightLoader. כל עוד הוא שם, KL_YTDLP וה-PATH לא מופעלים: במקומם היה נכנס {path}, והוא מדווח על {version}.',
  'settings.resolvers.toolsShadowedOlder': 'זהירות: העותק ש-KnightLoader הביא ({current}) ישן יותר מזה שממילא כבר יושב על המכונה הזאת ({system}, תחת {path}). עדכון קונטיינר מביא איתו yt-dlp חדש יותר, והעותק שלך עצמך לא זז איתו. הבא עותק חדש, או חזור לעותק המערכת.',
  'settings.resolvers.toolsManagedBroken': 'תחת {path} רשום עותק שהובא, והוא לא עולה. במקומו רצה הנפילה לאחור שלמעלה. הבא אותו מחדש, או חזור לעותק המערכת.',
  'settings.resolvers.toolsActions': 'לשמור על yt-dlp עדכני',
  'settings.resolvers.toolsActionsHint': 'ההבאה מורידה את yt-dlp מ-github.com, בודקת אותו מול הקובץ SHA2-256SUMS שפורסם באותה מהדורה, מפעילה אותו פעם אחת כדי לראות שהוא בכלל רץ על המכונה הזאת, ורק אז מניחה אותו לצד הנתונים שלך, במקום שממנו KnightLoader מפעיל אותו. עד הצעד האחרון הזה העותק שכבר היה לך ממשיך לעבוד, ואל ה-yt-dlp של המערכת שלך עצמה אף אחד לא נוגע.',
